// Regenerates onnx-data.js from the canonical artifacts in models/.
//
//   node scripts/build-onnx-data.mjs
//
// The generated file embeds the .onnx bytes, the vocabulary, and the Rust
// reference predictions so the lab can run the model from file:// with no
// fetch, no server, and no runtime dependency.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const onnx = fs.readFileSync(path.join(root, "models", "trot.onnx"));
const vocab = JSON.parse(fs.readFileSync(path.join(root, "models", "trot-vocab.json"), "utf8"));
const ref = JSON.parse(fs.readFileSync(path.join(root, "models", "trot-ref.json"), "utf8"));

const data = {
  bytesBase64: onnx.toString("base64"),
  bytes: onnx.length,
  hidden: vocab.hidden,
  vocab: vocab.vocab,
  reference: {
    inputs: ref.inputs,
    probs: ref.probs,
  },
};

const out = `// Generated by scripts/build-onnx-data.mjs — do not edit by hand.
// Source artifacts: models/trot.onnx, models/trot-vocab.json, models/trot-ref.json.
window.TROT_ONNX_DATA = ${JSON.stringify(data)};
`;

fs.writeFileSync(path.join(root, "onnx-data.js"), out);
console.log(
  `wrote onnx-data.js (${onnx.length} onnx bytes, ${vocab.vocab.length} tokens, ${ref.probs.length} reference predictions)`
);
